package com.thakur.employee.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Function;
@Service public class JwtService { @Value("${app.jwt.secret}") private String secret; @Value("${app.jwt.expiration-ms}") private long expiration; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(String username){return Jwts.builder().subject(username).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key()).compact();} public String username(String token){return claim(token,Claims::getSubject);} private <T>T claim(String token,Function<Claims,T> f){return f.apply(Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload());} public boolean valid(String token,String username){return username.equals(username(token))&&!claim(token,Claims::getExpiration).before(new Date());} }
